    font-size: 17px;
  }

  .metric-foot {
    font-size: 10px;
  }

  .panel-header {
    padding: 8px 10px;
  }

  .chart-body {
    padding: 8px 8px 6px;
  }

  .chart-svg-wrapper {
    height: 148px;
  }

  .filter-toolbar {
    padding: 8px 10px;
  }

  /* Transform Incident Table into High-Density Stacked Rows at <= 640px */
  .incident-table,
  .incident-table tbody {
    display: block;
    width: 100%;
  }

  .incident-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    border: 0;
  }

  .incident-row {
    display: grid;
    grid-template-columns: auto 1fr auto;
    grid-template-areas:
      "sev id status"
      "title title title"
      "service owner action";
    gap: 6px 8px;
    padding: 9px 10px;
    align-items: center;
  }

  .incident-row td {
    padding: 0;
    overflow: visible;
  }

  .incident-row.is-selected td:first-child {
    box-shadow: none;
  }

  .incident-row.is-selected {
    box-shadow: inset 3px 0 0 var(--accent);
  }

  .incident-row td.cell-sev {
    grid-area: sev;
  }

  .incident-row td.cell-id {
    grid-area: title;
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
  }

  .incident-row td.cell-service {
    grid-area: service;
  }

  .incident-row td.cell-age {
    grid-area: id;
    text-align: left;
  }

  .incident-row td.cell-owner {
    grid-area: owner;
    font-size: 11px;
  }

  .incident-row td.cell-status {
    grid-area: status;
    justify-self: end;
  }

  .incident-row td.cell-action {
    grid-area: action;
    justify-self: end;
  }

  .detail-body {
    padding: 10px;
  }
}

